Wrap the file reading operation in a `try-catch` block to handle missing or unreadable files gracefully. This prevents the script from throwing unhandled exceptions and crashing, allowing it to fail-closed by recording a validation failure diagnostic.

```javascript
async function scanFile(root, file) {
  const fullPath = path.join(root, file.path);
  let text;
  try {
    text = await fs.readFile(fullPath, 'utf8');
  } catch (error) {
    return {
      file,
      forbiddenViolations: [
        {
          category: file.category,
          path: file.path,
          line: 0,
          text: 'Failed to read file: ' + error.message,
          rule_id: 'file_read_failure',
          description: 'Critical file could not be read during scan.',
        },
      ],
      allowedReferences: [],
      neutralReferences: [],
    };
  }
  const lines = text.split(/\r?\n/u);
```

